import{_ as e,o as t,c as i,ag as s}from"./chunks/framework.CxkNbRKf.js";const n="/nada-documentation/images/data_tabs_script.png",o="/nada-documentation/images/image114.png",r="/nada-documentation/images/image115.png",b=JSON.parse('{"title":"Adding scripts","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/content/scripts.md","filePath":"admin-guide/content/scripts.md","lastUpdated":1786379412000}'),d={name:"admin-guide/content/scripts.md"};function l(c,a,p,h,u,m){return t(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="adding-scripts" tabindex="-1">Adding scripts <a class="header-anchor" href="#adding-scripts" aria-label="Permalink to &quot;Adding scripts&quot;">​</a></h1><p><img src="'+n+'" alt=""></p><p>Documenting, cataloguing and disseminating data has the potential to increase the volume and diversity of data analysis. There is also much value in documenting, cataloguing and disseminating <strong>data processing and analysis scripts</strong>. There are multiple reasons to include reproducibility, replicability, and auditability of data analytics as a component of a data dissemination system. They include:</p><ul><li>Improve the <strong>quality of research and analytical work</strong>. Public scrutiny enables contestability and independent quality control; it is a strong incentive for additional rigor.</li><li>Allow the <strong>re-purposing or expansion of analytical work</strong> by the research community, thereby increasing its relevance, utility and value of both the data and of the analytical work that makes use of them.</li><li>Protect the <strong>reputation and credibility</strong> of the analysis.</li><li>Provide students and researchers with useful <strong>training and reference materials</strong> on socio-economic development analysis.</li><li>Satisfy a <strong>requirement</strong> imposed by peer reviewed journals or financial sponsors of research.</li></ul><p>Technological solutions such as GitHub, Jupyter Notebooks and Jupiter Lab have been developed to facilitate the preservation, versioning, and sharing of code, and to enable collaborative work around data analysis. And recommendations and style guides have been produced to foster usability, adaptability, and reproducibility of code. But these solutions do not fully address the issue of discoverability of data analysis scripts, which requires better documentation and cataloguing solutions. We therefore propose --as a complement to existing solutions-- a metadata schema to document data analysis projects and the related scripts. The production of structured metadata will contribute not only to discoverability, but also to the reproducibility, replicability, and auditability of data analytics.</p><div class="tip custom-block"><p class="custom-block-title">Metadata schema</p><p>For documenting scripts/research projects, NADA uses a metadata schema developed by the World Bank Development Data Group.</p><p>The documentation of the script metadata schema is available at <a href="https://ihsn.github.io/nada-api-redoc/catalog-admin/#tag/Scripts" target="_blank" rel="noreferrer">https://ihsn.github.io/nada-api-redoc/catalog-admin/#tag/Scripts</a>. A Schema Guide is also available, which provides more detailed information on the structure, content, and use of the metadata standards and schemas.</p></div><h3 id="loading-metadata-web-interface" tabindex="-1">Loading metadata (web interface) <a class="header-anchor" href="#loading-metadata-web-interface" aria-label="Permalink to &quot;Loading metadata (web interface)&quot;">​</a></h3><p>This option is currently not available. It will be added in a future version of NADA.</p><h3 id="from-scratch-web-interface" tabindex="-1">From scratch (web interface) <a class="header-anchor" href="#from-scratch-web-interface" aria-label="Permalink to &quot;From scratch (web interface)&quot;">​</a></h3><p>You have the possibility to create a new <em>script</em> entry in the NADA administrator web interface, using the embedded metadata editor. A <em>script</em> entry is used to document and publish all scripts related to one same data processing and/or ananlysis project that involves scripts written in any programming language (R, Python, Stata, SPSS, SAS, other, or a combination of them). The objective of documenting and publishing scripts is to make research and analysis fully transparent, reproducible, and replicable. Ideally, the data that serve as input the the scripts, and the publications that are the output of the analysis, will also be documented and published in the catalog (as microdata, indicators, documents, tables, or other).</p><p>To document a research project (scripts) from scratch using the web interface, select &quot;Add study&quot; in the dashboard page, then select the option <em>script</em> in the <strong>Create new study</strong> box. Then click <strong>Create</strong>.</p><p><img src="'+o+'" alt=""></p><p>The <em>Overview</em> tab of a new, empty entry will be displayed. Click on the <strong>Metadata</strong> tab. The metadata editor embedded in NADA will be displayed, providing a form compliant with the NADA metadata schema for documenting data processing and analysis projects. After filling out the fields with as much detail as possible, click on <strong>Save</strong>.</p><p><img src="'+r+'" alt=""></p><p>Once you have entered and saved metadata, proceed as explained in previous section to upload files, select options, add a thumbnail, and publish your metadata. To add external resources, use the <strong>Add resource</strong> in the <em>External resources</em> page.</p><h3 id="loading-metadata-api" tabindex="-1">Loading metadata (API) <a class="header-anchor" href="#loading-metadata-api" aria-label="Permalink to &quot;Loading metadata (API)&quot;">​</a></h3><p>This option is currently not available. It will be added in a future version of NADA.</p><h3 id="from-scratch-api" tabindex="-1">From scratch (API) <a class="header-anchor" href="#from-scratch-api" aria-label="Permalink to &quot;From scratch (API)&quot;">​</a></h3><p>You can generate the metadata using R or Python, then publish it using the NADA API and the NADAR package or PyNADA library.</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-sSi8O" id="tab-TMEq0fl" checked><label data-title="R" for="tab-TMEq0fl">R</label><input type="radio" name="group-sSi8O" id="tab-rvMP9HJ"><label data-title="Python" for="tab-rvMP9HJ">Python</label></div><div class="blocks"><div class="language-r vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">r</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"></span></code></pre></div><div class="language-Python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"></span></code></pre></div></div></div>',20)])])}const f=e(d,[["render",l]]);export{b as __pageData,f as default};
